"use client";import {useState}from"react";import{api}from"../../lib/api";export default function Jobs(){const[id,setId]=useState("");const[result,setResult]=useState("");async function load(){const r=await api<unknown>(`/api/v1/jobs/${id}`);setResult(JSON.stringify(r.data??{error:r.error},null,2))}return <main className="route"><p className="eyebrow">WORKER OPERATIONS</p><h1>Job status</h1><input placeholder="Job UUID" value={id} onChange={e=>setId(e.target.value)}/><button className="primary" onClick={load}>Load job</button>{result&&<pre>{result}</pre>}</main>}
